<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require_once __DIR__.'/../includes/db.php';
function orderOut(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
try{$m=$_SERVER['REQUEST_METHOD']??'GET';
if($m==='GET'){$rows=$pdo->query("SELECT o.*,CONCAT_WS(' ',u.first_name,u.last_name) student_name,u.email,GROUP_CONCAT(CONCAT(c.title,' ×',oi.quantity) ORDER BY oi.id SEPARATOR ', ') courses FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN order_items oi ON oi.order_id=o.id LEFT JOIN courses c ON c.id=oi.course_id GROUP BY o.id ORDER BY o.created_at DESC,o.id DESC")->fetchAll();$stats=$pdo->query("SELECT SUM(status='pending') pending_count,COALESCE(SUM(CASE WHEN status='confirmed' AND DATE(confirmed_at)=CURRENT_DATE THEN net_amount ELSE 0 END),0) today_sales FROM orders")->fetch();orderOut(['orders'=>$rows,'stats'=>$stats]);}
if($m==='PATCH'){$d=json_decode(file_get_contents('php://input'),true);$id=(int)($d['id']??0);$status=(string)($d['status']??'');if($id<1||!in_array($status,['pending','confirmed','cancelled','refunded'],true))orderOut(['error'=>'ข้อมูลไม่ถูกต้อง'],422);$pdo->beginTransaction();$q=$pdo->prepare("UPDATE orders SET status=:status,confirmed_at=CASE WHEN :status2='confirmed' THEN COALESCE(confirmed_at,NOW()) ELSE confirmed_at END WHERE id=:id");$q->execute([':status'=>$status,':status2'=>$status,':id'=>$id]);if($status==='confirmed'){$q=$pdo->prepare("INSERT INTO enrollments(user_id,course_id,status) SELECT o.user_id,oi.course_id,'active' FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.id=:id AND NOT EXISTS(SELECT 1 FROM enrollments e WHERE e.user_id=o.user_id AND e.course_id=oi.course_id AND e.status='active')");$q->execute([':id'=>$id]);}$pdo->commit();orderOut(['success'=>true]);}orderOut(['error'=>'Method not allowed'],405);
}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Orders API: '.$e->getMessage());orderOut(['error'=>'ระบบคำสั่งซื้อขัดข้อง'],500);}
